function [plan,info] = capabilityMPC(x,t,theta,cfg,warm)
%CAPABILITYMPC Batched CEM, current physical state, no future disturbance.
% The paired nominal response is generated by this same feedback law.
% CEM is a finite-budget sampler; feasibility and optimality are not assumed.
clockIndex = round(t/cfg.dt);
stream = RandStream('mt19937ar','Seed',cfg.seed+clockIndex);
mu = warm(:);
sigma = 0.35*ones(cfg.H,1);
bestScore = inf;
plan = mu;
info = struct('feasible',false,'nominalCost',inf, ...
    'maxRaw',inf,'maxAngle',inf,'candidateTransitions',0);
for iter = 1:cfg.nIterations
    seq = mu+sigma.*randn(stream,cfg.H,cfg.nCandidates);
    seq = min(cfg.cMax,max(cfg.cMin,seq));
    seq(:,1) = plan;
    seq(:,2) = min(cfg.cMax,max(cfg.cMin,warm));
    seq(:,3) = min(cfg.cMax,max(cfg.cMin,(cfg.kv-cfg.dv)*x(3)/cfg.kv));
    seq(:,4) = 0;
    [cost,maxRaw,maxQ,violation] = rollout(x,t,seq,theta,cfg);
    feasible = maxRaw <= cfg.U+1e-9 & maxQ <= cfg.qMax+1e-9;
    % A finite penalty prioritizes feasible candidates in this probe.
    score = cost+100*violation+1e4*(~feasible);
    [scoreSorted,order] = sort(score);
    elite = seq(:,order(1:cfg.nElite));
    mu = mean(elite,2);
    sigma = max(0.025,std(elite,0,2));
    if scoreSorted(1) < bestScore
        bestScore = scoreSorted(1);
        ix = order(1);
        plan = seq(:,ix);
        info.feasible = feasible(ix);
        info.nominalCost = cost(ix);
        info.maxRaw = maxRaw(ix);
        info.maxAngle = maxQ(ix);
    end
end
info.candidateTransitions = cfg.nIterations*cfg.nCandidates*cfg.H*cfg.macroEvery;
end

function [cost,maxRaw,maxQ,violation] = rollout(x,t,seq,theta,cfg)
n = size(seq,2);
x = repmat(x,1,n);
cost = zeros(1,n);
violation = zeros(1,n);
maxRaw = zeros(1,n);
maxQ = abs(x(2,:));
for j = 1:cfg.H
    for k = 1:cfg.macroEvery
        raw = capabilityControlLaw(x,seq(j,:),theta,cfg);
        u = min(cfg.U,max(-cfg.U,raw));
        maxRaw = max(maxRaw,max(abs(raw),[],1));
        maxQ = max(maxQ,abs(x(2,:)));
        violation = violation+cfg.dt*(sum(max(abs(raw)-cfg.U,0).^2,1)+ ...
            10*max(abs(x(2,:))-cfg.qMax,0).^2);
        offset = ((j-1)*cfg.macroEvery+k-1)*cfg.dt;
        cost = cost+cfg.dt*capabilityStageCost(x,u,t+offset,cfg);
        % One RK4 integration step per feedback sample in prediction.
        x = capabilityIntegrate(x,u,0,cfg,1);
    end
end
maxQ = max(maxQ,abs(x(2,:)));
cost = cost+0.2*(cfg.weights(2)*x(2,:).^2+cfg.weights(4)*x(4,:).^2);
end
